fn solve(a: i8, b: i8, k: i8) -> (i8, i8) {
    // Remove up to k items from the first pile
    let remove_from_a = a.min(k);
    let a_remaining = a - remove_from_a;
    let remaining_k = k - remove_from_a;

    // With any leftover removals, remove from the second pile
    let remove_from_b = b.min(remaining_k);
    let b_remaining = b - remove_from_b;

    (a_remaining, b_remaining)
}

